export const TOOL_ALIASES: Record<string, string> = {
  // Image & Removal Aliases
  "object-remover": "object-remover-photo",
  "object-remover-ai": "object-remover-photo",
  "magic-object-remover": "object-remover-photo",
  "watermark-remover": "ai-watermark-remover",
  // SEO & Webmaster Aliases
  "open-graph-generator": "open-graph-preview",
  "ssl-certificate-checker": "ssl-checker",
  // Media Aliases
  "video-compressor-online": "video-compressor-advanced",
  "video-to-gif-converter": "video-to-gif-advanced",
  "screen-recorder-pro": "screen-recorder",
  // PDF Aliases
  "pdf-ocr-converter": "pdf-ocr",
  // AI Aliases
  "ai-grammar-checker": "grammar-checker-advanced",
  "ai-code-explainer": "ai-content-writer",
};

export function getDefaultToolBySlug(slug: string): DefaultTool | null {
  const resolvedSlug = TOOL_ALIASES[slug] || slug;
  return DEFAULT_TOOLS.find((t) => t.slug === resolvedSlug) || null;
}
